#!/bin/sh
# condense xdis disassembly lines (prefixed "# ") from stdin into one line per source line
sed 's/^# //' | grep -E "^[0-9]{4,5}:|^ +[0-9]+ |^ +>> " | sed -E 's/ +/ /g' | tr '\n' ' ' | sed -E 's/ ([0-9]{4,5}):/\n\1:/g' | sed -E 's/ [0-9]+ (LOAD_|STORE_|BINARY_|COMPARE_|POP_|JUMP|FOR_|GET_|BUILD_|FORMAT|INPLACE|CALL|UNPACK|ROT|DUP|EXTENDED|SETUP|RETURN|UNARY|MAKE|LIST|DELETE|BEGIN|END|WITH)/ \1/g; s/(LOAD_FAST|LOAD_CONST|LOAD_GLOBAL|LOAD_ATTR|LOAD_METHOD|STORE_FAST|STORE_ATTR|LOAD_DEREF|STORE_DEREF) \(([^)]*)\)/\2/g; s/CALL_METHOD \(([0-9]) positional arguments?\)/call\1/g; s/CALL_FUNCTION \(([0-9]) positional arguments?\)/call\1/g; s/BINARY_SUBSCR/[]/g; s/BINARY_MULTIPLY/*/g; s/BINARY_ADD/+/g; s/BINARY_SUBTRACT/-/g; s/BINARY_TRUE_DIVIDE/\//g; s/BINARY_FLOOR_DIVIDE/\/\//g; s/BINARY_MODULO/%/g; s/BINARY_POWER/**/g; s/EXTENDED_ARG \([0-9]+\) //g'
